aql:
LET counts = (
  FOR e IN directed
    COLLECT director = e._from WITH COUNT INTO movie_count
    RETURN { director, movie_count }
)
LET top = MAX(counts[*].movie_count)
FOR c IN counts
  FILTER c.movie_count == top
  SORT c.director
  RETURN { name: DOCUMENT(c.director).name, movie_count: c.movie_count }
